TLM.f("Tempora/Pent12-4",{"officium":"Feria Quinta infra Hebdomadam XII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent12-0","from":{"Introitus":"Tempora/Pent12-0","Oratio":"Tempora/Pent12-0","Lectio":"Tempora/Pent12-0","Graduale":"Tempora/Pent12-0","Evangelium":"Tempora/Pent12-0","Offertorium":"Tempora/Pent12-0","Secreta":"Tempora/Pent12-0","Communio":"Tempora/Pent12-0","Postcommunio":"Tempora/Pent12-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 69:2-3"},{"k":"text","la":"Deus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam."},{"k":"ref","la":"Ps 69:4"},{"k":"text","la":"Avertántur retrórsum et erubéscant: qui cógitant mihi mala."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Deus, in adjutórium meum inténde: Dómine, ad adjuvándum me festína: confundántur et revereántur inimíci mei, qui quærunt ánimam meam."}],"Oratio":[{"k":"text","la":"Omnípotens et miséricors Deus, de cujus múnere venit, ut tibi a fidélibus tuis digne et laudabíliter serviátur: tríbue, quǽsumus, nobis; ut ad promissiónes tuas sine offensióne currámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 3:4-9"},{"k":"text","la":"Fratres: Fidúciam talem habémus per Christum ad Deum: non quod sufficiéntes simus cogitáre áliquid a nobis, quasi ex nobis: sed sufficiéntia nostra ex Deo est: qui et idóneos nos fecit minístros novi testaménti: non líttera, sed spíritu: líttera enim occídit, spíritus autem vivíficat. Quod si ministrátio mortis, lítteris deformáta in lapídibus, fuit in glória; ita ut non possent inténdere fili Israël in fáciem Moysi, propter glóriam vultus ejus, quæ evacuátur: quómodo non magis ministrátio Spíritus erit in glória? Nam si ministrátio damnatiónis glória est multo magis abúndat ministérium justítiæ in glória."}],"Graduale":[{"k":"ref","la":"Ps 33:2-3"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"text","la":"In Dómino laudábitur ánima mea: áudiant mansuéti, et læténtur. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 87:2"},{"k":"text","la":"Dómine, Deus salútis meæ, in die clamávi et nocte coram te. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:23-37"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Beáti óculi, qui vident quæ vos videtis. Dico enim vobis, quod multi prophétæ et reges voluérunt vidére quæ vos videtis, et non vidérunt: et audire quæ audítis, et non audiérunt. Et ecce, quidam legisperítus surréxit, tentans illum, et dicens: Magister, quid faciéndo vitam ætérnam possidébo? At ille dixit ad eum: In lege quid scriptum est? quómodo legis? Ille respóndens, dixit: Díliges Dóminum, Deum tuum, ex toto corde tuo, et ex tota ánima tua, et ex ómnibus víribus tuis; et ex omni mente tua: et próximum tuum sicut teípsum. Dixítque illi: Recte respondísti: hoc fac, et vives. Ille autem volens justificáre seípsum, dixit ad Jesum: Et quis est meus próximus? Suscípiens autem Jesus, dixit: Homo quidam descendébat ab Jerúsalem in Jéricho, et íncidit in latrónes, qui étiam despoliavérunt eum: et plagis impósitis abiérunt, semivívo relícto. Accidit autem, ut sacerdos quidam descénderet eádem via: et viso illo præterívit. Simíliter et levíta, cum esset secus locum et vidéret eum, pertránsiit. Samaritánus autem quidam iter fáciens, venit secus eum: et videns eum, misericórdia motus est. Et apprópians, alligávit vulnera ejus, infúndens óleum et vinum: et impónens illum in juméntum suum, duxit in stábulum, et curam ejus egit. Et áltera die prótulit duos denários et dedit stabulário, et ait: Curam illíus habe: et quodcúmque supererogáveris, ego cum redíero, reddam tibi. Quis horum trium vidétur tibi próximus fuísse illi, qui íncidit in latrónes? At ille dixit: Qui fecit misericórdiam in illum. Et ait illi Jesus: Vade, et tu fac simíliter."}],"Offertorium":[{"k":"ref","la":"Exod 32:11 32:13; 32:14"},{"k":"text","la":"Precátus est Moyses in conspéctu Dómini, Dei sui, et dixit: Quare, Dómine, irásceris in pópulo tuo? Parce iræ ánimæ tuæ: meménto Abraham, Isaac et Jacob, quibus jurásti dare terram fluéntem lac et mel. Et placátus factus est Dóminus de malignitáte, quam dixit fácere pópulo suo."}],"Secreta":[{"k":"text","la":"Hóstias, quǽsumus, Dómine, propítius inténde, quas sacris altáribus exhibémus: ut, nobis indulgéntiam largiéndo, tuo nómini dent honórem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 103:13; 103:14-15"},{"k":"text","la":"De fructu óperum tuórum, Dómine, satiábitur terra: ut edúcas panem de terra, et vinum lætíficet cor hóminis: ut exhílaret fáciem in óleo, et panis cor hóminis confírmet."}],"Postcommunio":[{"k":"text","la":"Vivíficet nos, quǽsumus, Dómine, hujus participátio sancta mystérii: et páriter nobis expiatiónem tríbuat et múnimen."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1438b647d271ce64":{"t":"Ps 69, 2-3, Ps 69, 4\n(Ps 69, 2-3) Bože, u pomoć mi priteci! Gospodine, pohiti da mi pomogneš. Neka se smetu i postide koji traže moju dušu. (Ps 69, 4) Još jednom neka odstupe i zasrame se koji mi hoće zlo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 69, 2-3) Bože, u pomoć mi priteci! Gospodine, pohiti da mi pomogneš. Neka se smetu i postide koji traže moju dušu.","kn":"(Ps. 69, 2, 3). Bože, u pomoć mi priteci. Gospodine, pohiti da mi pomogneš! Nek se smetu i postide, koji traže dušu moju! (Ps. 69, 4). Još jednom neka se zasrame, koji ml hoće zlo. Slava Ocu . . . Bože, u pomoć . . .","knRef":"Kniewald 1942, str. 138–139 (snimka 70) (OCR)"},"e2850dc65b677bd9":{"t":"<i>Pomolimo se</i>.\nSvemogući i milosrdni Bože, po čijem daru dolazi da vjernici tebi dostojno i pohvalno služe, podaj nam, molimo, da bez spoticanja hrlimo k tvojim obećanjima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući i milosrdni Bože, od Tvojega dara dolazi, da Ti vjernici Tvoji dostojno i pohvalno služe: podaj nam, molimo, da k obećanjima Tvojim bez spoticanja hrlimo, po G. n.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"7615ea19e215214e":{"t":"2 Kor 3, 4-9\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, takvo pouzdanje imamo po Kristu u Boga. Ali to ne znači kao da bismo mogli što misliti sami po sebi, nego je naša sposobnost od Boga, koji nas učini sposobnim slugama Novoga zavjeta, ne po slovu nego po Duhu, jer slovo ubija, a Duh daje život. Kad je služba smrti, slovima urezana u kamenu, bila tako sjajna, da Izraelovi sinovi nisu mogli gledati Mojsijeva lica zbog prolaznog odsjeva njegova obličja, kako da ne bude slavnija služba Duha? Kad je slavna služba osude, neuporedivo je slavnija služba pravde.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 3, 4-0). Braćo! Takvo pouzdanje Po Kristu imamo u Boga, ne kao da bi mogli što prosuđivati sami od sebe, nego je naša snaga od Boga, koji nas je učinio sjKusobnim slugama Novo'ga Zavjeta: Ne po slovu, nego po Duhu, jer slovo ubija, a Duh daje život. Ako je služba smrti, izražena slovima na kamenju, bila tako slavna, da Izraelovi sinovi nijesu mogli gledati Mojsljeva lica radi prolazne slave njegova lica, kako da ne bude slavnija služba Duha? Jer, ako je slavna služba osude, daleko je slavnija služba pravde.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"96ffa1e2cb0c7cc1":{"t":"Ps 33, 2-3\nBlagoslivljat ću Gospodina u svako doba. Njegova je hvala uvijek na mojim ustima. U Gospodinu neka se hvali moja duša, neka čuju ponizni i razvesele se.\n\nPs 87, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodine, Bože spasenja mojega, danju i noću vapijem pred tobom. <i>Aleluja</i>.","kn":"(Ps. 33, 2-3). Blagosiljat ću Gospodina u svako doba, vazda je hvala njegova u ustima mojim, U Gospodinu će se hvaliti duša moja, neka čuju krotki, pa, neka se raduju.\n\nAleluja, aleluja. (Ps: 87, 2) Gospodine, Bože spasenja mojega, danju i noću vapijem pred Tobom.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"ca24e64833ee0805":{"t":"Lk 10, 23-37\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Blago očima, koje vide što vi vidite, jer, kažem vam, mnogi su proroci i kraljevi željeli vidjeti što vi vidite, i nisu vidjeli, i čuti što vi čujete, i nisu čuli. Tada pristupi neki učitelj Zakona, pa ga upita s nakanom da ga kuša: Učitelju, što treba da činim, da zaslužim vječni život? Isus upita njega: Što je pisano u Zakonu? Kako čitaš? Onaj odgovori: Ljubi Gospodina svojega Boga svim svojim srcem, svom svojom dušom, svom svojom snagom i svim svojim umom, a svojega bližnjega kao samoga sebe. I reče mu: Pravo si odgovorio, čini to i živjet ćeš! Ali on hoteći se opravdati upita Isusa: A tko je moj bližnji? Tada Isus reče: Neki je čovjek putovao iz Jeruzalema u Jerihon i upadne u ruke razbojnika. Oni ga svuku, izrane, ostave napola mrtva pa otiđu. Dogodi se, da je onim putem prolazio svećenik. On ga opazi i prođe dalje. Isto tako i levit kad je bio kraj toga mjesta, opazi ga i prođe. A neki Samaritanac putujući dođe do njega. Kad ga vidje, sažali mu se, i pristupi k njemu, opere mu rane uljem i vinom pa ih zavije. Onda ga posadi na svoje živinče, dovede ga u gostionicu i pobrinu se za njega. Sutradan izvadi dva dinara, dade ih gostioničaru i reče: Brini se za njega. I što potrošiš više, kada se vratim, ja ću ti platiti. Što ti se čini: Koji je od ove trojice bio bližnji onome, koji je upao među razbojnike? Zakonoznanac odgovori: Onaj koji mu iskaza milosrđe. Isus mu reče: Idi i čini i ti tako!","kn":"t Slijedi sveto evanđelje po Luki (10, 23-37). U ono vrijenie reče Isus svojim učenicima: Blago očima, koje vide, što vi vidite! Jer kažem vam, da su mnogi^ proroci i kraljevi željeli vidjeti, što vi vidite, i nijesu vidjeli, i čuti, što vi čujete, a nijesu čuli. Tada ustade neki zakonoznanac, da ga kuša i reče: Učitelju, što moram činiti, da zado~ bijem vječni život? A on ga upita: Sto je pisano u zakonu? Kako čitaš? On mu odgovori: Ljubi Gospodina Boga svoga svim šrcem svojim, i svom dušom svojom, i svom snagom svojom i svim umom r svojim, a svoga bližnjega kao samoga sebe. I reče mu: Pravo si odgovorio; to čini i živjet' ćeš! Ali ovaj hoteći se opravdati upita Isusa: A tko je mo'j bližnji? Prihvativ Isus reče: Neki' je čovjek silazio iz Jeruzalema u Jerihon i upadne među razbojnike, koji ga opljačkaše, izraniše i otiđoše,. a njaga ostave na po mrtva. Onim je putem silazio neki svećenik, vidje ga i prođe. Tako i levita, kad je bio kraj toga mjesta, vidje ga i prođe. A putujući, neki Samaritanae dođe do njega, vidje ga i sažali mu se. I pristupi k njemu, zavi mu rane, zali uljem i vinom, posadi ga na svoje živinče, dovede ga u gostionicu i pobrinu se za njega. I sutradan izvadi dva dinara, dade ih gostioničaru i. reče: Brini se za njega, i što više potrošiš, platit ću ti, kad se vratim. Sto misliš: Koji je od ove trojice bio bližnji onomu, koji je upao među nazbojnike? A on od-, govori: Koji mu se smilovao! I reče mu Isus: Idi, i ti čini taho! ■","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"e375459a23628a91":{"t":"Izl 32, 11 i 13 i 14\nMolio se Mojsije pred licem svoga Boga i rekao: Zašto se, Gospodine, srdiš na svoj narod? Odvrati se od svoga gnjeva. Sjeti se Abrahama, Izaka i Jakova kojima si se zakleo da ćeš im dati zemlju u kojoj teče mlijeko i med. I sažali se Gospodinu te ne učini zlo koje je smislio učiniti svome narodu.","kn":"(Ižl. 32, 11-14). Molio je Mojsije Go- Epodin'a Boga svoga govoreći: Zašto izlijevaš, .Gospodine, srdžbu svoju na narod svoj? Ublaži srdžbu svoju i sjeti se Abrahama, Izaka, i Jakova, kojima si se zakleo, da' ćeš im dati zemlju, kojom teče mlijeko i med: I ublažio je Gospodin srdžbu svoju.","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"4cbab5833d8d6b0a":{"t":"Žrtvene darove što ti ih na svetim oltarima prinosimo, molimo, Gospodine, primi dobrostivo, da djelujući nama na oproštenje iskažu čast tvojem imenu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, pogledaj dobrostivo žrtve, što ih na svetim žrtvenicima prinosimo, da nama darujući oproštenje podaju ča^st. Tvojemu imenu, po G. n.","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"37464e62f5d58140":{"t":"Ps 103, 13 i 14-15\nPlodom se tvojih djela, Gospodine, siti zemlja. Izvodiš kruh iz zemlje i vino da razveseli srce čovjeku. Od ulja se svijetli lice, a kruh krijepi srce čovjeku.","kn":"(Ps. 103, 12-15). Plodom se djela T'voj ih, Gospodine, siti zemlja, da izvedeš hljeb iz zemlje i vino da veseli srce čovječje; .da mu se lice sja od ulja i da kruh. krijepi: srce ...čovječje.","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"331c5b1b49f6ad68":{"t":"<i>Pomolimo se</i>.\nNeka nam, molimo, Gospodine, sudjelovanje u ovome svetom otajstvu dade život i neka nam bude na pomirbu i zaštitu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
